typedef struct { int token; int method; const char* uri; const void* payload; int payload_len; } coap_request_t;
typedef struct { int code; } coap_response_t;

int coap_check_permission(coap_request_t* req) { return 1; }
void coap_enforce_permission(coap_request_t* req) { (void)req; }
void coap_log_denied(coap_request_t* req) { (void)req; }
void config_store_write(const char* uri, const void* data, int len) { (void)uri; (void)data; (void)len; }

void coap_handle_config_write(coap_request_t* req, coap_response_t* resp)
{
  if (!coap_check_permission(req)) {
    coap_log_denied(req);
    resp->code = 401;
    return;
  }
  coap_enforce_permission(req);
  config_store_write(req->uri, req->payload, req->payload_len);
  resp->code = 204;
}

void coap_handle_ping(coap_request_t* req, coap_response_t* resp)
{
  resp->code = 200;
}
